package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class AlertsActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Land Alerts","Risk and record-change signals linked to your parcels.");DatabaseManager m=new DatabaseManager(this);String uid=new AuthManager(this).getUserId();Cursor c=m.getDatabase().rawQuery("SELECT a.alert_type,a.description,a.severity,a.risk_score,a.status FROM ai_alerts a JOIN parcels p ON a.ulpin=p.ulpin JOIN users u ON p.owner_name=u.name WHERE u.id=? ORDER BY a.detected_date DESC",new String[]{uid});try{if(!c.moveToFirst())root.addView(utils.text(this,"No active land alerts.",15,0xff71808f,false));else do{LinearLayout box=utils.column(this);utils.row(box,this,"Type",c.getString(0));utils.row(box,this,"Severity",c.getString(2));utils.row(box,this,"Risk Score",String.valueOf(c.getInt(3)));utils.row(box,this,"Status",c.getString(4));box.addView(utils.text(this,c.getString(1),14,0xff183b56,false));utils.addCard(root,box,this);}while(c.moveToNext());}finally{c.close();}utils.setScreenContentView(this, root);}}
